#!/usr/bin/env python3
"""Turn composed level GLBs into complete ValTraining map folders.

For every map folder (``<out>/<key>`` holding the level GLBs written by compose_map.py and
flatten_glb.py) this writes ``manifest.json`` and ``collision.json``:

* The frame origin puts the drilled bomb site's plant point at x = z = 0 (Bind and Ascent
  keep the frame their hand-authored drills use: Ascent's is unchanged, Bind's is the
  east-west mirror of the old one, see compose_map.py), and the floor there at y = 0.
* Collision is generated by gen_collision.py over the whole map: the clip volume is the
  bounding box of every official callout (valorant-api.com) plus a margin, instead of the
  ±50 m around one drill the old files covered.

Usage:
  python build_maps.py <out dir> <api_maps.json> [key ...]
"""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import gen_collision as gc  # noqa: E402

# key -> (Unreal map token, drilled site, fixed origin or None)
MAPS = {
    "ascent": ("Ascent", "A", (50.0, -3.8, 61.0)),
    "bind": ("Duality", "B", (49.17, -2.6, 119.08)),
    "breeze": ("Foxtrot", "A", None),
    "haven": ("Triad", "C", None),
    "icebox": ("Port", "B", None),
    "split": ("Bonsai", "A", None),
    "fracture": ("Canyon", "A", None),
    "lotus": ("Jam", "A", None),
    "pearl": ("Pitt", "A", None),
    "abyss": ("Infinity", "A", None),
    "sunset": ("Juliett", "A", None),
    "summit": ("Plummet", "A", None),
    "corrode": ("Rook", "A", None),
}


def api_map(api, token):
    for m in api:
        if m.get("mapUrl", "").split("/")[-1].lower() == token.lower():
            return m
    raise KeyError(token)


def site_point(m, site):
    for c in m["callouts"]:
        if c["superRegionName"] == site and c["regionName"] == "Site":
            return c["location"]
    raise KeyError(f"{m['displayName']}: no {site} Site callout")


def floor_at(boxes, x, z, y_hint, radius=1.5):
    """Highest walkable top within `radius` of (x, z) that is at most 3 m above y_hint."""
    if not boxes:
        return None
    b = np.asarray(boxes, dtype=np.float64)
    sel = ((b[:, 0] <= x + radius) & (b[:, 3] >= x - radius) & (b[:, 2] <= z + radius) & (b[:, 5] >= z - radius)
           & (b[:, 4] <= y_hint + 3.0))
    if not sel.any():
        return None
    return float(b[sel, 4].max())


def build(folder: Path, key: str, api):
    token, site, fixed = MAPS[key]
    m = api_map(api, token)
    sp = site_point(m, site)
    levels = sorted(p.stem for p in folder.glob("*.glb"))
    if fixed:
        origin = list(fixed)
    else:
        origin = [-sp["y"] / 100.0, -sp.get("z", 0) / 100.0, sp["x"] / 100.0]

    def game(loc):
        return (loc["y"] / 100 + origin[0], loc.get("z", 0) / 100 + origin[1], -loc["x"] / 100 + origin[2])

    pts = np.array([game(c["location"]) for c in m["callouts"]])
    margin = 16.0
    clip = (pts[:, 0].min() - margin, pts[:, 1].min() - 12.0, pts[:, 2].min() - margin,
            pts[:, 0].max() + margin, pts[:, 1].max() + 18.0, pts[:, 2].max() + margin)

    def write_manifest():
        (folder / "manifest.json").write_text(json.dumps({
            "key": key, "map": token,
            "origin_x": round(origin[0], 3), "origin_y": round(origin[1], 3), "origin_z": round(origin[2], 3),
            "site_letter": site, "site": list(map(lambda v: round(v, 3), game(sp))),
            "levels": levels,
        }, indent=2))

    write_manifest()
    os.environ["MAPGEN_CLIP"] = ",".join(f"{v:.2f}" for v in clip)
    print(f"[{key}] {token} site {site}: origin {np.round(origin, 2).tolist()} clip {np.round(clip, 1).tolist()}", flush=True)
    boxes, tris = gc.generate(str(folder), verbose=False)

    if not fixed:
        # Put the floor of the plant point at y = 0.
        x, y, z = game(sp)
        f = floor_at(boxes, x, z, y + 1.0)
        if f is not None and abs(f) > 0.01:
            for bx in boxes:
                bx[1] -= f
                bx[4] -= f
            origin[1] -= f
            write_manifest()
            clip_y = (clip[1] - f, clip[4] - f)
            print(f"    floor at site {f:+.2f} m -> origin_y {origin[1]:.2f} (clip y {clip_y[0]:.1f}..{clip_y[1]:.1f})")
        else:
            print(f"    floor at site: {f}")
    (folder / "collision.json").write_text(json.dumps({"boxes": boxes}, separators=(",", ":")))
    print(f"    {len(levels)} levels, {tris} tris -> {len(boxes)} boxes", flush=True)


def main(argv):
    if len(argv) < 3:
        print(__doc__)
        return 2
    out = Path(argv[1])
    api = json.load(open(argv[2], encoding="utf-8"))["data"]
    keys = argv[3:] or list(MAPS)
    for key in keys:
        folder = out / key
        if not folder.is_dir():
            print(f"[{key}] missing {folder}")
            continue
        build(folder, key, api)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
